import java.sql.*; public class ShowSchema { public static void main(String[] a) throws Exception { Connection c = DriverManager.getConnection("jdbc:mysql://localhost:3306/travelmate_db?allowPublicKeyRetrieval=true&useSSL=false","root","root"); ResultSet rs = c.getMetaData().getColumns(null,null,"users",null); while(rs.next()) System.out.println(rs.getString("COLUMN_NAME") + " | null=" + rs.getString("IS_NULLABLE")); c.close(); } }